import os,json,urllib.request
base='https://api.assemblyai.com/v2'
def call(path,data):
 req=urllib.request.Request(base+path,data=data,headers={'Authorization':os.environ['ASSEMBLYAI_API_KEY'],'Content-Type':'application/json' if path"'!='"'/upload' else 'application/octet-stream'})
 try:return json.load(urllib.request.urlopen(req,timeout=60))
 except urllib.error.HTTPError as e:raise RuntimeError(f'{e.code}: {e.read().decode()}')
u=call('/upload',open('sample.wav','rb').read());open('/tmp/aai-upload.json','w').write(json.dumps(u)); print('Upload complete')
r=call('/transcript',json.dumps({'audio_url':u['upload_url'],'language_code':'en_uk','speech_models':['universal-2'],'punctuate':True,'format_text':True}).encode());open('/tmp/aai-test.json','w').write(json.dumps(r));print(json.dumps(r))
PY"

